#pragma once

#include <cstdint>

// Ad catalog: a table for looking up vanilla ads from the hashes of their files.
// The data is in plugin/src/generated/AdCatalog.inc, generated by tools/catalog.
namespace AdCatalog
{
enum class FileKind : uint8_t
{
    Image,    // .xbm
    Atlas,    // .inkatlas
    Widget,   // .inkwidget
    Animation, // .inkanim (not copied, the vanilla file stays referenced)
    Other,
};

struct File
{
    const char* path; // e.g. base\gameplay\gui\world\adverts\naranjita\naranjita_atlas.xbm
    FileKind kind;
};

struct Record
{
    const char* name;              // e.g. Adverts.Naranjita
    const char* widget;            // path of the .inkwidget the resource points to
    const char* const* districts;  // district lists the record is in (e.g. Adverts.Kabuki.advertisements)
    uint16_t districtCount;
};

struct Ad
{
    const char* folder; // ad folder, ending with a separator (e.g. base\gameplay\gui\world\adverts\naranjita followed by a separator)
    const File* files;
    uint16_t fileCount;
    const Record* records;
    uint16_t recordCount;
};

struct Catalog
{
    const char* gameVersion;          // game version the catalog was made for (for the log)
    uint32_t tweakDbChecksum;         // record checksum in the tweakdb.bin header
    uint32_t tweakDbEp1Checksum;      // the same value in tweakdb_ep1.bin
    const Ad* ads;
    uint16_t adCount;
};

const Catalog& Get();
} // namespace AdCatalog
